import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Globe, 
  Monitor, 
  Play, 
  Square, 
  Sparkles, 
  Bot, 
  Terminal, 
  CheckCircle2, 
  AlertCircle, 
  RefreshCw, 
  ExternalLink,
  Cpu,
  Layers,
