  Key
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface ExecutionLog {
  timestamp: string;
  type: 'action' | 'thought' | 'result' | 'error';
  message: string;
}

export default function ComputerUseTab() {
  const [goal, setGoal] = useState('');
  const [selectedAgent, setSelectedAgent] = useState<'agent-s3' | 'unbrowse' | 'browser-use' | 'open-interpreter' | 'playwright-mcp'>('agent-s3');
  const [selectedModel, setSelectedModel] = useState('ornith-1.0-35b-moe');
  const [isRunning, setIsRunning] = useState(false);
  const [logs, setLogs] = useState<ExecutionLog[]>([
    { timestamp: '10:12:00', type: 'thought', message: 'Initialized Agent S3 + UI-TARS 2 Desktop & Web Controller v4.0.' },
    { timestamp: '10:12:01', type: 'action', message: 'Mapped VLM visual grounding engine to Ornith-1.0-35B / UI-TARS 2.' },
    { timestamp: '10:12:02', type: 'result', message: 'Stateless MCP Server protocol active with Mcp-Method header routing.' }
  ]);

  const handleStartMission = async () => {
    if (!goal.trim()) return;
    setIsRunning(true);

    const newLog: ExecutionLog = {
      timestamp: new Date().toLocaleTimeString(),
      type: 'action',
      message: `Executing goal via [${selectedAgent}] using model [${selectedModel}]: "${goal}"`
    };

    setLogs(prev => [newLog, ...prev]);

    try {
      const res = await fetch('/api/automation/browser-agent', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ goal, agent: selectedAgent, model: selectedModel })
      });
      const data = await res.json();

      setLogs(prev => [
        {
          timestamp: new Date().toLocaleTimeString(),
          type: data.success ? 'result' : 'error',
          message: data.message || JSON.stringify(data)
        },
        ...prev
      ]);
    } catch (err: any) {
      setLogs(prev => [
        {
          timestamp: new Date().toLocaleTimeString(),
          type: 'error',
          message: `Execution failed: ${err.message || err}`
        },
        ...prev
      ]);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="w-full max-w-7xl mx-auto space-y-6 animate-in fade-in zoom-in duration-500 p-4">
      {/* Header Banner */}
      <div className="relative overflow-hidden bg-gradient-to-r from-cyan-900/30 via-slate-900/60 to-purple-900/30 border border-cyan-500/30 rounded-[32px] p-8 backdrop-blur-xl shadow-2xl flex items-center justify-between">
        <div className="flex items-center gap-6 z-10">
          <div className="p-4 bg-gradient-to-br from-cyan-500 to-blue-600 rounded-2xl shadow-lg">
            <Globe className="w-10 h-10 text-white" />
          </div>
          <div>
            <h1 className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 via-blue-200 to-indigo-100 tracking-tight flex items-center gap-3">
              Browser & Computer Use Automation
            </h1>
            <p className="text-cyan-200/70 font-medium tracking-wide mt-1 flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-cyan-400" /> Powered by `browser-use`, Playwright MCP & UI-TARS Visual Grounding
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3 z-10">
          <span className="px-4 py-2 bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 rounded-xl text-xs font-bold uppercase tracking-wider flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
            Playwright MCP Online
          </span>
        </div>
      </div>

      {/* Main Execution Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Mission Control */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-900/50 border border-slate-800 rounded-3xl p-6 backdrop-blur-xl space-y-6">
            <h2 className="text-lg font-bold text-white flex items-center gap-2">
              <Bot className="w-5 h-5 text-cyan-400" /> Agent & Engine Selection
            </h2>

            {/* Framework Choice */}
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">Framework Engine</label>
              <div className="grid grid-cols-1 gap-2">
                {[
                  { id: 'agent-s3', name: '🤖 Agent S3 (UI-TARS 2)', desc: '#1 OSWorld benchmark — human-level desktop GUI control' },
                  { id: 'unbrowse', name: '⚡ Unbrowse (API-First)', desc: 'Direct REST/GraphQL reverse-engineering — 10x faster' },
                  { id: 'browser-use', name: '🌐 browser-use (Python)', desc: 'Natural language web navigation & DOM parsing' },
                  { id: 'open-interpreter', name: '🖥️ OpenInterpreter OS', desc: 'Desktop screenshot VLM coordinate clicking' },
                  { id: 'playwright-mcp', name: '🔌 Playwright Stateless MCP', desc: 'July 2026 spec header-routed accessibility driver' }
                ].map(item => (
                  <button
                    key={item.id}
                    onClick={() => setSelectedAgent(item.id as any)}
                    className={cn(
                      "p-3 rounded-2xl border text-left transition-all",
                      selectedAgent === item.id 
                        ? "bg-cyan-500/10 border-cyan-500/50 text-cyan-300 shadow-lg shadow-cyan-500/10" 
                        : "bg-slate-800/40 border-slate-700/50 text-slate-400 hover:text-white"
                    )}
                  >
                    <div className="font-bold text-sm text-white">{item.name}</div>
                    <div className="text-[10px] opacity-70 mt-0.5">{item.desc}</div>
                  </button>
                ))}
              </div>
            </div>

            {/* Model Selection */}
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">VLM & Agent Model</label>
              <select
                value={selectedModel}
                onChange={e => setSelectedModel(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 text-white rounded-xl p-3 text-xs font-medium outline-none focus:border-cyan-500"
              >
                <option value="ornith-1.0-35b-moe">Ornith 1.0 35B (Local MoE — 75.6% SWE-Bench)</option>
                <option value="ornith-1.0-9b">Ornith 1.0 9B (Local Dense — 69.4% SWE-Bench)</option>
                <option value="qwen3-coder-30b">Qwen3 Coder 30B (Local MoE 3.3B Active)</option>
                <option value="qwythos-9b">Qwythos 9B (Claude Mythos Distill — 1M Ctx)</option>
                <option value="google/gemini-2.0-flash-001">Gemini 2.0 Flash (Cloud Free API)</option>
                <option value="qwen/qwen2.5-vl-72b-instruct:free">Qwen 2.5 VL 72B (Free OpenRouter VLM)</option>
                <option value="anthropic/claude-3-5-sonnet">Claude 3.5 Sonnet (Computer Use API)</option>
              </select>
            </div>

            {/* Natural Language Prompt */}
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">Automation Goal</label>
              <textarea
                value={goal}
                onChange={e => setGoal(e.target.value)}
                placeholder="e.g. Go to GitHub Trending, find top 3 Python AI projects, and extract their descriptions..."
                rows={4}
                className="w-full bg-slate-950 border border-slate-800 text-white rounded-xl p-3 text-xs outline-none focus:border-cyan-500 placeholder-slate-600 font-mono resize-none"
              />
            </div>

            <button
              onClick={handleStartMission}
              disabled={isRunning || !goal.trim()}
              className={cn(
                "w-full py-4 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 shadow-lg",
                isRunning 
                  ? "bg-amber-500/20 text-amber-400 border border-amber-500/40 cursor-wait" 
                  : "bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-400 hover:to-blue-500 text-white shadow-cyan-500/25"
              )}
            >
              {isRunning ? (
                <>
                  <RefreshCw className="w-4 h-4 animate-spin" /> Executing Autonomous Workflow...
                </>
              ) : (
                <>
                  <Play className="w-4 h-4 fill-current" /> Launch Natural Language Mission
                </>
              )}
            </button>
          </div>
        </div>

        {/* Right Column: Live Terminal & Execution Feed */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-slate-900/50 border border-slate-800 rounded-3xl p-6 backdrop-blur-xl h-full flex flex-col min-h-[480px]">
            <div className="flex items-center justify-between mb-4 border-b border-slate-800 pb-4">
              <h3 className="text-base font-bold text-white flex items-center gap-2">
                <Terminal className="w-5 h-5 text-emerald-400" /> Visual & Execution Log Feed
              </h3>
              <span className="text-[10px] font-mono text-slate-400 bg-slate-800 px-3 py-1 rounded-full">
                Real-time Telemetry
              </span>
            </div>

            <div className="flex-1 bg-slate-950 rounded-2xl border border-slate-800/80 p-4 font-mono text-xs overflow-y-auto space-y-3 custom-scrollbar">
              <AnimatePresence>
                {logs.map((log, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    className={cn(
                      "p-3 rounded-xl border flex items-start gap-3",
                      log.type === 'action' ? "bg-cyan-950/30 border-cyan-800/40 text-cyan-300" :
                      log.type === 'thought' ? "bg-purple-950/30 border-purple-800/40 text-purple-300" :
                      log.type === 'result' ? "bg-emerald-950/30 border-emerald-800/40 text-emerald-300" :
                      "bg-rose-950/30 border-rose-800/40 text-rose-300"
                    )}
                  >
                    <span className="text-[10px] opacity-60 shrink-0 mt-0.5">{log.timestamp}</span>
                    <div className="flex-1 leading-relaxed">{log.message}</div>
                  </motion.div>
                ))}
              </AnimatePresence>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

#!/usr/bin/env python3
"""
CUAI Dual-Layer Visual & Accessibility Tree Grounder (SoM - Set of Mark).

Combines:
  1. Accessibility Tree & DOM Interactive Element Extraction.
  2. Numbered Visual Grid Overlays (Set-of-Mark Prompting).
  3. Pixel-level bounding box mapping for zero-hallucination clicks.
"""

from __future__ import annotations

import base64
import json
import os
import re
import sys
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

from PIL import Image, ImageDraw, ImageFont

CUAI_DIR = Path(r"C:\Users\karma\CUAI")
SCREENSHOT_DIR = CUAI_DIR / "screenshots"
SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)


class DualLayerGrounder:
    """Extracts interactive UI elements and draws numbered labels for LLM vision grounding."""

    def __init__(self):
        self.font = self._get_font(14)

    def _get_font(self, size: int):
        try:
            return ImageFont.truetype("arial.ttf", size)
        except Exception:
            return ImageFont.load_default()

    def annotate_screenshot_with_marks(
        self,
        image_path: Path,
        elements: List[Dict[str, Any]],
        output_path: Optional[Path] = None,
    ) -> Tuple[Path, str]:
        """Draw numbered bounding boxes (Set-of-Mark) over all clickable elements."""
        img = Image.open(image_path).convert("RGBA")
        overlay = Image.new("RGBA", img.size, (0, 0, 0, 0))
        draw = ImageDraw.Draw(overlay)

        colors = [
            (239, 68, 68, 180),   # Red
            (59, 130, 246, 180),  # Blue
            (16, 185, 129, 180),  # Emerald
            (245, 158, 11, 180),  # Amber
            (139, 92, 246, 180),  # Purple
        ]

        for idx, el in enumerate(elements, start=1):
            box = el.get("box", {})
            x, y, w, h = box.get("x", 0), box.get("y", 0), box.get("w", 0), box.get("h", 0)
            if w <= 0 or h <= 0:
                continue

            color = colors[(idx - 1) % len(colors)]
            draw.rectangle([x, y, x + w, y + h], outline=color, width=2)

            # Draw badge background
            badge_w, badge_h = 24, 18
            draw.rectangle([x, max(0, y - badge_h), x + badge_w, y], fill=color)
            draw.text((x + 4, max(0, y - badge_h) + 2), str(idx), fill=(255, 255, 255, 255), font=self.font)

        annotated = Image.alpha_composite(img, overlay).convert("RGB")
        target_path = output_path or SCREENSHOT_DIR / "annotated_som.png"
        annotated.save(target_path, "PNG")

        with open(target_path, "rb") as f:
            b64 = base64.b64encode(f.read()).decode("utf-8")

        return target_path, b64

    @staticmethod
    async def extract_interactive_dom_elements(page) -> List[Dict[str, Any]]:
        """Extract all interactive buttons, links, inputs, and aria elements with bounding boxes."""
        script = """() => {
            const items = [];
            const selectors = [
                'button', 'a[href]', 'input', 'select', 'textarea',
                '[role="button"]', '[role="link"]', '[role="checkbox"]',
                '[role="tab"]', '[role="menuitem"]', '[aria-label]',
                '[tabindex]:not([tabindex="-1"])', 'audio', '[data-track-id]'
            ];

            const nodes = document.querySelectorAll(selectors.join(', '));
            nodes.forEach((el, index) => {
                const rect = el.getBoundingClientRect();
                const style = window.getComputedStyle(el);

                if (rect.width > 6 && rect.height > 6 && style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0') {
                    items.push({
                        id: index + 1,
                        tag: el.tagName.toLowerCase(),
                        text: (el.innerText || el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('title') || '').slice(0, 60).replace(/\\s+/g, ' ').strip(),
                        type: el.getAttribute('type') || '',
                        role: el.getAttribute('role') || '',
                        box: {
                            x: Math.round(rect.left),
                            y: Math.round(rect.top),
                            w: Math.round(rect.width),
                            h: Math.round(rect.height),
                            cx: Math.round(rect.left + rect.width / 2),
                            cy: Math.round(rect.top + rect.height / 2)
                        }
                    });
                }
            });
            return items.slice(0, 80);
        }"""
        try:
            return await page.evaluate(script)
        except Exception:
            return []


def main():
    print("[+] DualLayerGrounder (Set-of-Mark & AXTree) initialized.")
    grounder = DualLayerGrounder()
    print("    Ready for DOM extraction and numbered overlay synthesis.")


if __name__ == "__main__":
    main()

